window.PMP_WORDS = (window.PMP_WORDS || []).concat([
{"id":181,"en":"Rough Order of Magnitude (ROM)","say":"Rough Order of Magnitude","also":["rom"],"gloss":"粗略量级估算","explain":"项目很早时的粗估，区间大约是负 25% 到正 75%。","band":"规划","ipa":"rəf ˈɔrdər əv ˈmægnəˌtud"},
{"id":182,"en":"Definitive Estimate","say":"Definitive Estimate","also":[],"gloss":"确定性估算","explain":"一个估算结果或估算类型。数字会随信息变多而收窄。","band":"规划","ipa":"dɪˈfɪnɪtɪv ˈɛstəˌmeɪt"},
{"id":960,"en":"Performance Budget","say":"Performance Budget","also":[],"gloss":"性能预算","explain":"事先定好的帧时间、内存或包体上限。超了就要裁内容或做优化。","band":"规划","ipa":"pərˈfɔrməns ˈbəʤɪt","tag":"游戏"},
{"id":905,"en":"Mood Board","say":"Mood Board","also":[],"gloss":"情绪板","explain":"用图片和色彩拼出期望的感觉，帮助对齐设计和体验。","band":"规划","ipa":"mud bɔrd"},
{"id":906,"en":"Storyboard","say":"Storyboard","also":[],"gloss":"故事板","explain":"用一组画面把用户如何使用产品的过程讲出来。","band":"规划","ipa":"ˈstɔriˌbɔrd"},
{"id":183,"en":"Change Request","say":"Change Request","also":[],"gloss":"变更请求","explain":"正式提出的修改，可以是纠正、预防、缺陷补救或计划更新。","band":"治理","ipa":"ʧeɪnʤ rɪkˈwɛst"},
{"id":184,"en":"Change Log","say":"Change Log","also":[],"gloss":"变更日志","explain":"项目进行中用来跟踪某一类事项的清单。","band":"治理","ipa":"ʧeɪnʤ lɔg"},
{"id":185,"en":"Change Control","say":"Change Control","also":[],"gloss":"变更控制","explain":"提议、审查、批准和跟踪变更的一整套做法。","band":"治理","ipa":"ʧeɪnʤ kənˈtroʊl"},
{"id":186,"en":"Integrated Change Control","say":"Integrated Change Control","also":[],"gloss":"整体变更控制","explain":"从项目整体审查变更对范围、进度、成本等的影响，再决定批不批。","band":"治理","ipa":"ˈɪnəˌgreɪtɪd ʧeɪnʤ kənˈtroʊl"},
{"id":187,"en":"Change Control Board (CCB)","say":"Change Control Board","also":["ccb"],"gloss":"变更控制委员会","explain":"负责审查、批准或否决变更的一组人。","band":"治理","ipa":"ʧeɪnʤ kənˈtroʊl bɔrd"},
{"id":188,"en":"Change Control System","say":"Change Control System","also":[],"gloss":"变更控制系统","explain":"规定变更如何提交、谁审批、如何记录的一套程序和工具。","band":"治理","ipa":"ʧeɪnʤ kənˈtroʊl ˈsɪstəm"},
{"id":189,"en":"Configuration Management","say":"Configuration Management","also":[],"gloss":"配置管理","explain":"识别成果的版本，控制其变更，并随时能说清当前配置。","band":"治理","ipa":"kənˌfɪgjərˈeɪʃən ˈmænɪʤmənt"},
{"id":190,"en":"Configuration Management System","say":"Configuration Management System","also":[],"gloss":"配置管理系统","explain":"用来提交、跟踪和批准配置项变更的程序和工具。","band":"治理","ipa":"kənˌfɪgjərˈeɪʃən ˈmænɪʤmənt ˈsɪstəm"},
{"id":191,"en":"Version Control","say":"Version Control","also":[],"gloss":"版本控制","explain":"给文件和产品保留版本，避免大家改的不是同一份。","band":"治理","ipa":"ˈvərʒən kənˈtroʊl"},
{"id":192,"en":"Corrective Action","say":"Corrective Action","also":[],"gloss":"纠正措施","explain":"把已经偏掉的绩效拉回计划的措施。事情已经发生了。","band":"治理","ipa":"kərˈɛktɪv ˈækʃən"},
{"id":193,"en":"Preventive Action","say":"Preventive Action","also":[],"gloss":"预防措施","explain":"为了防止以后发生偏差而提前做的措施。","band":"治理","ipa":"prɪˈvɛnɪv ˈækʃən"},
{"id":194,"en":"Defect Repair","say":"Defect Repair","also":[],"gloss":"缺陷补救","explain":"修补有缺陷的成果，使它重新符合要求。","band":"治理","ipa":"ˈdifɛkt rɪˈpɛr"},
{"id":195,"en":"Approved Change Request","say":"Approved Change Request","also":[],"gloss":"批准的变更请求","explain":"已经通过审批、可以拿去执行的变更。","band":"治理","ipa":"əˈpruvd ʧeɪnʤ rɪkˈwɛst"},
{"id":196,"en":"Work Performance Data","say":"Work Performance Data","also":[],"gloss":"工作绩效数据","explain":"执行中收集的原始记录，比如完成了百分之几、花了多少钱。","band":"治理","ipa":"wərk pərˈfɔrməns ˈdætə"},
{"id":197,"en":"Work Performance Information","say":"Work Performance Information","also":[],"gloss":"工作绩效信息","explain":"把原始数据对照基准分析之后得到的信息，比如偏差和指数。","band":"治理","ipa":"wərk pərˈfɔrməns ˌɪnˌfɔrˈmeɪʃən"},
{"id":198,"en":"Work Performance Report","say":"Work Performance Report","also":[],"gloss":"工作绩效报告","explain":"把绩效信息汇编成干系人能看的报告。","band":"治理","ipa":"wərk pərˈfɔrməns rɪˈpɔrt"},
{"id":199,"en":"Issue Log","say":"Issue Log","also":[],"gloss":"问题日志","explain":"项目进行中用来跟踪某一类事项的清单。","band":"治理","ipa":"ˈɪʃu lɔg"},
{"id":200,"en":"Assumption Log","say":"Assumption Log","also":[],"gloss":"假设日志","explain":"项目进行中用来跟踪某一类事项的清单。","band":"治理","ipa":"əˈsəmpʃən lɔg"},
{"id":201,"en":"Lessons Learned Register","say":"Lessons Learned Register","also":[],"gloss":"经验教训登记册","explain":"持续更新的名册，把识别出来的对象一条条记下来。","band":"治理","ipa":"ˈlɛsənz ˈlərnɪd ˈrɛʤɪstər"},
{"id":202,"en":"Stakeholder Register","say":"Stakeholder Register","also":[],"gloss":"干系人登记册","explain":"持续更新的名册，把识别出来的对象一条条记下来。","band":"治理","ipa":"ˈsteɪˌkhoʊldər ˈrɛʤɪstər"},
{"id":203,"en":"Risk Register","say":"Risk Register","also":[],"gloss":"风险登记册","explain":"持续更新的名册，把识别出来的对象一条条记下来。","band":"治理","ipa":"rɪsk ˈrɛʤɪstər"},
{"id":204,"en":"Risk Report","say":"Risk Report","also":[],"gloss":"风险报告","explain":"整理给干系人看的正式信息，不是原始流水账。","band":"治理","ipa":"rɪsk rɪˈpɔrt"},
{"id":205,"en":"Enterprise Environmental Factors (EEF)","say":"Enterprise Environmental Factors","also":["eef"],"gloss":"事业环境因素","explain":"项目团队控制不了、但会影响项目的条件，来自组织内外。","band":"治理","ipa":"ˈɛnərˌpraɪz ɪnˌvaɪrənˈmɛnəl ˈfæktərz"},
{"id":206,"en":"Organizational Process Assets (OPA)","say":"Organizational Process Assets","also":["opa"],"gloss":"组织过程资产","explain":"组织积累的流程、模板、政策和历史经验，项目可以拿来用。","band":"治理","ipa":"ˌɔrgənəˈzeɪʃənəl ˈprɔˌsɛs ˈæˌsɛts"},
{"id":207,"en":"Historical Information","say":"Historical Information","also":[],"gloss":"历史信息","explain":"过去项目留下的数据和教训，估算和规划时拿来参考。","band":"治理","ipa":"hɪˈstɔrɪkəl ˌɪnˌfɔrˈmeɪʃən"},
{"id":208,"en":"Lessons Learned Repository","say":"Lessons Learned Repository","also":[],"gloss":"经验教训库","explain":"组织存放经验教训的地方，新项目开始时应该去查。","band":"治理","ipa":"ˈlɛsənz ˈlərnɪd riˈpɑzəˌtɔri"},
{"id":209,"en":"Organizational Knowledge Repository","say":"Organizational Knowledge Repository","also":[],"gloss":"组织知识库","explain":"组织的知识库，包括问题、缺陷、财务数据和经验。","band":"治理","ipa":"ˌɔrgənəˈzeɪʃənəl ˈnɑlɪʤ riˈpɑzəˌtɔri"},
{"id":210,"en":"Project Management Information System (PMIS)","say":"Project Management Information System","also":["pmis"],"gloss":"项目管理信息系统","explain":"收集、整合和分发项目信息的系统，排进度和汇总绩效常用它。","band":"治理","ipa":"ˈprɑʤɛkt ˈmænɪʤmənt ˌɪnˌfɔrˈmeɪʃən ˈsɪstəm"},
{"id":211,"en":"Work Authorization System","say":"Work Authorization System","also":[],"gloss":"工作授权系统","explain":"正式批准某项工作可以开始的程序，防止没准备好就开工。","band":"治理","ipa":"wərk ˌɔθərəˈzeɪʃən ˈsɪstəm"},
{"id":212,"en":"Explicit Knowledge","say":"Explicit Knowledge","also":[],"gloss":"显性知识","explain":"能写进文档、用文字和数字传给别人的知识。","band":"治理","ipa":"ɪkˈsplɪsət ˈnɑlɪʤ"},
{"id":213,"en":"Tacit Knowledge","say":"Tacit Knowledge","also":[],"gloss":"隐性知识","explain":"经验、直觉和难言传的诀窍，要靠交流才能传递。","band":"治理","ipa":"ˈtæsɪt ˈnɑlɪʤ"},
{"id":214,"en":"Knowledge Management","say":"Knowledge Management","also":[],"gloss":"知识管理","explain":"让人把隐性经验分享出来，而不是只整理文档。","band":"治理","ipa":"ˈnɑlɪʤ ˈmænɪʤmənt"},
{"id":435,"en":"Individual Project Risk","say":"Individual Project Risk","also":[],"gloss":"单个项目风险","explain":"还没发生的不确定事件。先分清它是威胁还是机会。","band":"治理","ipa":"ˌɪndəˈvɪʤəwəl ˈprɑʤɛkt rɪsk"},
{"id":436,"en":"Overall Project Risk","say":"Overall Project Risk","also":[],"gloss":"整体项目风险","explain":"还没发生的不确定事件。先分清它是威胁还是机会。","band":"治理","ipa":"ˈoʊvərˌɔl ˈprɑʤɛkt rɪsk"},
{"id":437,"en":"Threat","say":"Threat","also":[],"gloss":"威胁","explain":"一旦发生会对目标造成损害的风险。","band":"治理","ipa":"θrɛt"},
{"id":961,"en":"Platform Waiver","say":"Platform Waiver","also":[],"gloss":"平台豁免","explain":"平台或发行书面同意：某个已知问题可以带着上线，不必在这一版修掉。合同里的弃权是另一回事。","band":"治理","ipa":"ˈplætˌfɔrm ˈweɪvər","tag":"游戏"},
{"id":438,"en":"Opportunity","say":"Opportunity","also":[],"gloss":"机会","explain":"一旦发生会对目标有利的风险。","band":"治理","ipa":"ˌɑpərˈtunəti"},
{"id":439,"en":"Risk Appetite","say":"Risk Appetite","also":[],"gloss":"风险偏好","explain":"为了预期回报，组织愿意承担多大的不确定性。","band":"治理","ipa":"rɪsk ˈæpəˌtaɪt"},
{"id":440,"en":"Risk Tolerance","say":"Risk Tolerance","also":[],"gloss":"风险承受力","explain":"组织或干系人还能忍受的风险程度。","band":"治理","ipa":"rɪsk ˈtɑlərəns"},
{"id":441,"en":"Risk Threshold","say":"Risk Threshold","also":[],"gloss":"风险临界值","explain":"围绕目标可以接受的偏差界限，越过就要采取行动。","band":"治理","ipa":"rɪsk θˈrɛˌʃoʊld"},
{"id":442,"en":"Risk Exposure","say":"Risk Exposure","also":[],"gloss":"风险敞口","explain":"风险可能带来的整体影响程度。","band":"治理","ipa":"rɪsk ɪkˈspoʊʒər"},
{"id":443,"en":"Risk Breakdown Structure (RBS)","say":"Risk Breakdown Structure","also":["rbs"],"gloss":"风险分解结构","explain":"按类别把风险来源分层，帮助把风险识别全。","band":"治理","ipa":"rɪsk ˈbreɪkˌdaʊn ˈstrəkʧər"},
{"id":444,"en":"Probability and Impact Matrix","say":"Probability and Impact Matrix","also":[],"gloss":"概率和影响矩阵","explain":"一种组织或分析表。若是组织结构，核心是项目经理和职能经理如何分权。","band":"治理","ipa":"ˌprɑbəˈbɪləˌti ənd ˌɪmˈpækt ˈmeɪtrɪks"},
{"id":445,"en":"Qualitative Risk Analysis","say":"Qualitative Risk Analysis","also":[],"gloss":"定性风险分析","explain":"一种分析技术，用来比较方案、追查原因或预测结果。","band":"治理","ipa":"kˈwɑləˌteɪtɪv rɪsk æˈnælɪsɪs"},
{"id":446,"en":"Quantitative Risk Analysis","say":"Quantitative Risk Analysis","also":[],"gloss":"定量风险分析","explain":"一种分析技术，用来比较方案、追查原因或预测结果。","band":"治理","ipa":"kˈwɑntɪˌteɪtɪv rɪsk æˈnælɪsɪs"},
{"id":447,"en":"Risk Score","say":"Risk Score","also":[],"gloss":"风险分值","explain":"通常用概率乘以影响得到的分值，用来排优先级。","band":"治理","ipa":"rɪsk skɔr"},
{"id":448,"en":"Risk Owner","say":"Risk Owner","also":[],"gloss":"风险责任人","explain":"负责监视某个风险并执行应对的人。","band":"治理","ipa":"rɪsk ˈoʊnər"},
{"id":449,"en":"Risk Trigger","say":"Risk Trigger","also":[],"gloss":"风险触发条件","explain":"说明风险即将发生或已经发生的征兆。","band":"治理","ipa":"rɪsk ˈtrɪgər"},
{"id":450,"en":"Risk Response","say":"Risk Response","also":[],"gloss":"风险应对","explain":"针对威胁或机会预先定好的处理办法。","band":"治理","ipa":"rɪsk rɪˈspɑns"},
{"id":451,"en":"Avoid","say":"Avoid","also":[],"gloss":"规避","explain":"对付威胁的策略：消灭威胁本身，或让项目碰不到它。","band":"治理","ipa":"əˈvɔɪd"},
{"id":452,"en":"Transfer","say":"Transfer","also":[],"gloss":"转移","explain":"把威胁的影响和应对责任转给第三方，比如买保险或外包。","band":"治理","ipa":"ˈtrænsfər"},
{"id":453,"en":"Mitigate","say":"Mitigate","also":[],"gloss":"减轻","explain":"降低威胁发生的概率或影响，是最常用的主动应对。","band":"治理","ipa":"ˈmɪtəˌgeɪt"},
{"id":454,"en":"Accept","say":"Accept","also":[],"gloss":"接受","explain":"承认风险在，但不主动改计划。可以预留应急，也可以什么都不做。","band":"治理","ipa":"əkˈsɛpt"},
{"id":455,"en":"Escalate","say":"Escalate","also":[],"gloss":"上报","explain":"风险超出项目范围或项目经理权限时，交给上一层处理。","band":"治理","ipa":"ˈɛskəˌleɪt"},
{"id":456,"en":"Exploit","say":"Exploit","also":[],"gloss":"开拓","explain":"对付机会的策略：确保这个好事一定发生。","band":"治理","ipa":"ˌɛkˈsplɔɪt"},
{"id":457,"en":"Share","say":"Share","also":[],"gloss":"分享","explain":"把机会分给最能抓住它的第三方，双方共享收益。","band":"治理","ipa":"ʃɛr"},
{"id":458,"en":"Enhance","say":"Enhance","also":[],"gloss":"提高","explain":"提高机会发生的概率，或把好处放大。","band":"治理","ipa":"ɛnˈhæns"},
{"id":459,"en":"Contingency Plan","say":"Contingency Plan","also":[],"gloss":"应急计划","explain":"事先写好、等风险触发才执行的应对方案。","band":"治理","ipa":"kənˈtɪnʤənsi plæn"},
{"id":460,"en":"Fallback Plan","say":"Fallback Plan","also":[],"gloss":"弹回计划","explain":"应急计划失败时的退路。","band":"治理","ipa":"ˈfɔlˌbæk plæn"},
{"id":461,"en":"Workaround","say":"Workaround","also":[],"gloss":"权变措施","explain":"风险发生后临时想出来的办法。事先没有写进应对计划。","band":"治理","ipa":"workaround"},
{"id":462,"en":"Residual Risk","say":"Residual Risk","also":[],"gloss":"残余风险","explain":"采取应对之后仍然留下来的风险。","band":"治理","ipa":"rɪˈzɪʤuəl rɪsk"},
{"id":463,"en":"Secondary Risk","say":"Secondary Risk","also":[],"gloss":"次生风险","explain":"因为采取应对措施而新冒出来的风险。","band":"治理","ipa":"ˈsɛkənˌdɛri rɪsk"},
{"id":464,"en":"Watch List","say":"Watch List","also":[],"gloss":"观察清单","explain":"当前优先级不高、但还要留意的风险清单。","band":"治理","ipa":"wɔʧ lɪst"},
{"id":465,"en":"Contingent Response Strategy","say":"Contingent Response Strategy","also":[],"gloss":"应急应对策略","explain":"只有某个触发条件出现时才执行的应对。","band":"治理","ipa":"kənˈtɪnʤənt rɪˈspɑns ˈstrætəʤi"},
{"id":466,"en":"Expected Monetary Value (EMV)","say":"Expected Monetary Value","also":["emv"],"gloss":"预期货币价值","explain":"概率乘以影响，用来给不确定的结果一个货币值。","band":"治理","ipa":"ɪkˈspɛktɪd ˈmɑnəˌtɛri ˈvælju"},
{"id":467,"en":"Decision Tree Analysis","say":"Decision Tree Analysis","also":[],"gloss":"决策树分析","explain":"一种分析技术，用来比较方案、追查原因或预测结果。","band":"治理","ipa":"dɪˈsɪʒən tri æˈnælɪsɪs"},
{"id":468,"en":"Sensitivity Analysis","say":"Sensitivity Analysis","also":[],"gloss":"敏感性分析","explain":"一种分析技术，用来比较方案、追查原因或预测结果。","band":"治理","ipa":"ˌsɛnsɪˈtɪvɪti æˈnælɪsɪs"},
{"id":469,"en":"Tornado Diagram","say":"Tornado Diagram","also":[],"gloss":"龙卷风图","explain":"用图把关系、流程或原因摊开，方便团队一起看。","band":"治理","ipa":"tɔrˈneɪˌdoʊ ˈdaɪəˌgræm"},
{"id":470,"en":"Monte Carlo Simulation","say":"Monte Carlo Simulation","also":[],"gloss":"蒙特卡洛模拟","explain":"用大量随机试验看进度或成本的可能分布，而不是只给一个单点。","band":"治理","ipa":"ˈmɑnti ˈkɑrloʊ ˌsɪmjəˈleɪʃən"},
{"id":471,"en":"Simulation","say":"Simulation","also":[],"gloss":"模拟","explain":"用模型反复试算不确定的进度或成本，蒙特卡洛是其中一种。","band":"治理","ipa":"ˌsɪmjəˈleɪʃən"},
{"id":472,"en":"Influence Diagram","say":"Influence Diagram","also":[],"gloss":"影响图","explain":"用图把关系、流程或原因摊开，方便团队一起看。","band":"治理","ipa":"ˈɪnfluəns ˈdaɪəˌgræm"},
{"id":962,"en":"Known Issue","say":"Known Issue","also":[],"gloss":"已知问题","explain":"已经确认、并决定这一版暂不修或带说明发布的问题。提审时要列出来。","band":"治理","ipa":"noʊn ˈɪʃu","tag":"游戏"},
{"id":473,"en":"SWOT Analysis","say":"SWOT Analysis","also":[],"gloss":"SWOT 分析","explain":"一种分析技术，用来比较方案、追查原因或预测结果。","band":"治理","ipa":"ɛs ˈdʌbəlju oʊ ti æˈnælɪsɪs"},
{"id":474,"en":"Root Cause Analysis","say":"Root Cause Analysis","also":[],"gloss":"根本原因分析","explain":"一种分析技术，用来比较方案、追查原因或预测结果。","band":"治理","ipa":"rut kɔz æˈnælɪsɪs"},
{"id":475,"en":"Assumptions and Constraints Analysis","say":"Assumptions and Constraints Analysis","also":[],"gloss":"假设和制约因素分析","explain":"一种分析技术，用来比较方案、追查原因或预测结果。","band":"治理","ipa":"əˈsəmpʃənz ənd kənˈstreɪnts æˈnælɪsɪs"},
{"id":476,"en":"Prompt List","say":"Prompt List","also":[],"gloss":"提示清单","explain":"预先列好的风险类别清单，用来提醒团队还有哪些方面没想到。","band":"治理","ipa":"prɑmpt lɪst"},
{"id":477,"en":"Risk Data Quality Assessment","say":"Risk Data Quality Assessment","also":[],"gloss":"风险数据质量评估","explain":"看风险数据是否准确、客观、完整，避免用烂信息排优先级。","band":"治理","ipa":"rɪsk ˈdætə kˈwɑləti əˈsɛsmənt"},
{"id":478,"en":"Risk Categorization","say":"Risk Categorization","also":[],"gloss":"风险分类","explain":"按来源、工作包或阶段给风险分组，找出集中的风险地带。","band":"治理","ipa":"rɪsk ˌkætəgərɪˈzeɪʃən"},
{"id":479,"en":"Representations of Uncertainty","say":"Representations of Uncertainty","also":[],"gloss":"不确定性表现方式","explain":"用概率分布等方式把“不准”表达出来，而不是假装一个单点。","band":"治理","ipa":"ˌrɛprəzənˈteɪʃənz əv ənˈsərtənti"},
{"id":480,"en":"Technical Performance Analysis","say":"Technical Performance Analysis","also":[],"gloss":"技术绩效分析","explain":"一种分析技术，用来比较方案、追查原因或预测结果。","band":"治理","ipa":"ˈtɛknɪkəl pərˈfɔrməns æˈnælɪsɪs"},
{"id":481,"en":"Reserve Analysis","say":"Reserve Analysis","also":[],"gloss":"储备分析","explain":"一种分析技术，用来比较方案、追查原因或预测结果。","band":"治理","ipa":"rɪˈzərv æˈnælɪsɪs"},
{"id":482,"en":"Risk Audit","say":"Risk Audit","also":[],"gloss":"风险审计","explain":"检查风险应对是否按计划执行、是否有效。","band":"治理","ipa":"rɪsk ˈɔdɪt"},
{"id":483,"en":"Risk Review","say":"Risk Review","also":[],"gloss":"风险审查","explain":"定期看风险状态有没有变化，并识别新风险。","band":"治理","ipa":"rɪsk ˌrivˈju"},
{"id":484,"en":"Cost of Quality (COQ)","say":"Cost of Quality","also":["coq"],"gloss":"质量成本","explain":"为了达到质量而花的钱，加上因为没达到质量而亏的钱。","band":"治理","ipa":"kɔst əv kˈwɑləti"},
{"id":485,"en":"Cost of Conformance","say":"Cost of Conformance","also":[],"gloss":"一致性成本","explain":"一次做对的花费，包括预防和评估。","band":"治理","ipa":"kɔst əv kənˈfɔrməns"},
{"id":486,"en":"Cost of Nonconformance","say":"Cost of Nonconformance","also":[],"gloss":"非一致性成本","explain":"没做对的代价，包括内部失败和外部失败。","band":"治理","ipa":"kɔst əv nonconformance"},
{"id":487,"en":"Prevention Cost","say":"Prevention Cost","also":[],"gloss":"预防成本","explain":"和钱、预算或成本绩效有关。","band":"治理","ipa":"priˈvɛnʃən kɔst"},
{"id":488,"en":"Appraisal Cost","say":"Appraisal Cost","also":[],"gloss":"评估成本","explain":"和钱、预算或成本绩效有关。","band":"治理","ipa":"əˈpreɪzəl kɔst"},
{"id":489,"en":"Internal Failure Cost","say":"Internal Failure Cost","also":[],"gloss":"内部失败成本","explain":"和钱、预算或成本绩效有关。","band":"治理","ipa":"ˌɪnˈtərnəl ˈfeɪljər kɔst"},
{"id":490,"en":"External Failure Cost","say":"External Failure Cost","also":[],"gloss":"外部失败成本","explain":"和钱、预算或成本绩效有关。","band":"治理","ipa":"ɪkˈstərnəl ˈfeɪljər kɔst"},
{"id":491,"en":"Prevention","say":"Prevention","also":[],"gloss":"预防","explain":"把缺陷挡在发生之前。质量管理更强调预防，而不是事后检查。","band":"治理","ipa":"priˈvɛnʃən"},
{"id":492,"en":"Accuracy","say":"Accuracy","also":[],"gloss":"准确度","explain":"结果离真实值有多近。","band":"治理","ipa":"ˈækjərəsi"},
{"id":493,"en":"Precision","say":"Precision","also":[],"gloss":"精确度","explain":"多次结果彼此有多接近。可以很精确但并不准确。","band":"治理","ipa":"priˈsɪʒən"},
{"id":494,"en":"Quality Metric","say":"Quality Metric","also":[],"gloss":"质量测量指标","explain":"用来衡量质量的具体指标，比如缺陷密度或按时率。","band":"治理","ipa":"kˈwɑləti ˈmɛtrɪk"},
{"id":495,"en":"Quality Report","say":"Quality Report","also":[],"gloss":"质量报告","explain":"整理给干系人看的正式信息，不是原始流水账。","band":"治理","ipa":"kˈwɑləti rɪˈpɔrt"},
{"id":496,"en":"Test and Evaluation Documents","say":"Test and Evaluation Documents","also":[],"gloss":"测试与评估文件","explain":"用来检查成果是否合格的测试脚本和记录。","band":"治理","ipa":"tɛst ənd ɪˌvæljuˈeɪʃən ˈdɑkjəmənts"},
{"id":497,"en":"Quality Audit","say":"Quality Audit","also":[],"gloss":"质量审计","explain":"独立查看过程有没有按质量计划执行。","band":"治理","ipa":"kˈwɑləti ˈɔdɪt"},
{"id":498,"en":"Process Analysis","say":"Process Analysis","also":[],"gloss":"过程分析","explain":"一种分析技术，用来比较方案、追查原因或预测结果。","band":"治理","ipa":"ˈprɔˌsɛs æˈnælɪsɪs"},
{"id":499,"en":"Quality Improvement","say":"Quality Improvement","also":[],"gloss":"质量改进","explain":"有针对性地把过程或成果做得更符合要求。","band":"治理","ipa":"kˈwɑləti ˌɪmˈpruvmənt"},
{"id":500,"en":"Continuous Improvement","say":"Continuous Improvement","also":[],"gloss":"持续改进","explain":"持续小步地改进过程和成果，而不是等出大事再改。","band":"治理","ipa":"kənˈtɪnjuəs ˌɪmˈpruvmənt"},
{"id":501,"en":"Checklist","say":"Checklist","also":[],"gloss":"核查表","explain":"用来确认该做的步骤有没有做的清单。","band":"治理","ipa":"ˈʧɛˌklɪst"},
{"id":502,"en":"Cause-and-Effect Diagram","say":"Cause-and-Effect Diagram","also":[],"gloss":"因果图","explain":"用图把关系、流程或原因摊开，方便团队一起看。","band":"治理","ipa":"kɔz ənd ˈifɛkt ˈdaɪəˌgræm"},
{"id":503,"en":"Fishbone Diagram","say":"Fishbone Diagram","also":[],"gloss":"鱼骨图","explain":"用图把关系、流程或原因摊开，方便团队一起看。","band":"治理","ipa":"fishbone ˈdaɪəˌgræm"},
{"id":504,"en":"Ishikawa Diagram","say":"Ishikawa Diagram","also":[],"gloss":"石川图","explain":"用图把关系、流程或原因摊开，方便团队一起看。","band":"治理","ipa":"ˌɪˌʃiˈkɑˌwɑ ˈdaɪəˌgræm"},
{"id":505,"en":"Flowchart","say":"Flowchart","also":[],"gloss":"流程图","explain":"把过程的步骤和分支画出来，方便找遗漏和等待。","band":"治理","ipa":"ˈfloʊˌʧɑrt"},
{"id":506,"en":"Histogram","say":"Histogram","also":[],"gloss":"直方图","explain":"用柱子显示数据落在各个区间的次数。","band":"治理","ipa":"ˈhɪstəˌgræm"},
{"id":507,"en":"Pareto Chart","say":"Pareto Chart","also":[],"gloss":"帕累托图","explain":"用图形看计划或状态，比纯表格更快发现落后。","band":"治理","ipa":"pareto ʧɑrt"},
{"id":963,"en":"Age Rating","say":"Age Rating","also":[],"gloss":"年龄分级","explain":"ESRB、PEGI 等机构给游戏标的适龄等级。上架前通常要先完成。","band":"治理","ipa":"eɪʤ ˈreɪtɪŋ","tag":"游戏"},
{"id":508,"en":"Control Chart","say":"Control Chart","also":[],"gloss":"控制图","explain":"监控过程：拿实际和基准比，管住偏差，需要时提出变更。","band":"治理","ipa":"kənˈtroʊl ʧɑrt"},
{"id":509,"en":"Scatter Diagram","say":"Scatter Diagram","also":[],"gloss":"散点图","explain":"用图把关系、流程或原因摊开，方便团队一起看。","band":"治理","ipa":"ˈskætər ˈdaɪəˌgræm"},
{"id":510,"en":"Affinity Diagram","say":"Affinity Diagram","also":[],"gloss":"亲和图","explain":"用图把关系、流程或原因摊开，方便团队一起看。","band":"治理","ipa":"əˈfɪnɪti ˈdaɪəˌgræm"},
{"id":511,"en":"Matrix Diagram","say":"Matrix Diagram","also":[],"gloss":"矩阵图","explain":"用图把关系、流程或原因摊开，方便团队一起看。","band":"治理","ipa":"ˈmeɪtrɪks ˈdaɪəˌgræm"},
{"id":512,"en":"Statistical Sampling","say":"Statistical Sampling","also":[],"gloss":"统计抽样","explain":"抽一部分来推断整体，而不是每件都查。","band":"治理","ipa":"stəˈtɪstɪkəl ˈsæmplɪŋ"},
{"id":513,"en":"Attribute Sampling","say":"Attribute Sampling","also":[],"gloss":"属性抽样","explain":"结果只分合格或不合格。","band":"治理","ipa":"əˈtrɪˌbjut ˈsæmplɪŋ"},
{"id":514,"en":"Variable Sampling","say":"Variable Sampling","also":[],"gloss":"变量抽样","explain":"结果用连续的数值来衡量，比如尺寸偏差多少。","band":"治理","ipa":"ˈvɛriəbəl ˈsæmplɪŋ"},
{"id":515,"en":"Control Limit","say":"Control Limit","also":[],"gloss":"控制界限","explain":"监控过程：拿实际和基准比，管住偏差，需要时提出变更。","band":"治理","ipa":"kənˈtroʊl ˈlɪmət"},
{"id":516,"en":"Specification Limit","say":"Specification Limit","also":[],"gloss":"规格界限","explain":"客户或合同要求的合格界限，和控制图上的控制界限不是一回事。","band":"治理","ipa":"ˌspɛsɪfɪˈkeɪʃən ˈlɪmət"},
{"id":517,"en":"Rule of Seven","say":"Rule of Seven","also":[],"gloss":"七点规则","explain":"控制图上连续七点落在中心线同一侧，说明过程可能失控，即使都在界限内。","band":"治理","ipa":"rul əv ˈsɛvən"},
{"id":518,"en":"Benchmarking","say":"Benchmarking","also":[],"gloss":"标杆对照","explain":"拿自己的做法和标杆比较，找出可以改进的差距。","band":"治理","ipa":"benchmarking"},
{"id":519,"en":"Design of Experiments (DOE)","say":"Design of Experiments","also":["doe"],"gloss":"实验设计","explain":"有计划地改变若干因素，找出哪个因素真正影响结果。","band":"治理","ipa":"dɪˈzaɪn əv ɪkˈspɛrəmənts"},
{"id":520,"en":"Design for X (DfX)","say":"Design for X","also":["dfx"],"gloss":"面向 X 的设计","explain":"设计时就针对某一目标优化，比如可制造性、可靠性或成本。","band":"治理","ipa":"dɪˈzaɪn fər ɛks"},
{"id":521,"en":"Plan-Do-Check-Act (PDCA)","say":"Plan-Do-Check-Act","also":["pdca"],"gloss":"计划—实施—检查—处置","explain":"戴明循环：计划、实施、检查、处置，用来持续改进。","band":"治理","ipa":"plæn du ʧɛk ækt"},
{"id":522,"en":"Total Quality Management (TQM)","say":"Total Quality Management","also":["tqm"],"gloss":"全面质量管理","explain":"全员、全过程都对质量负责的管理思路。","band":"治理","ipa":"ˈtoʊtəl kˈwɑləti ˈmænɪʤmənt"},
{"id":523,"en":"Six Sigma","say":"Six Sigma","also":[],"gloss":"六西格玛","explain":"用数据和统计把缺陷降到极低水平的改进方法。","band":"治理","ipa":"sɪks ˈsɪgmə"},
{"id":524,"en":"DMAIC","say":"DMAIC","also":[],"gloss":"定义、测量、分析、改进、控制","explain":"六西格玛的改进步骤：定义、测量、分析、改进、控制。","band":"治理","ipa":"di ɛm eɪ aɪ si"},
{"id":525,"en":"Just in Time (JIT)","say":"Just in Time","also":["jit"],"gloss":"准时制","explain":"需要时才生产或送达，减少库存和等待。","band":"治理","ipa":"ʤɪst ɪn taɪm"},
{"id":526,"en":"Kaizen","say":"Kaizen","also":[],"gloss":"改善","explain":"持续的小改善，强调每个人都参与。","band":"治理","ipa":"kaizen"},
{"id":527,"en":"Fitness for Use","say":"Fitness for Use","also":[],"gloss":"适用性","explain":"朱兰的说法：产品适合客户实际使用，才算质量好。","band":"治理","ipa":"ˈfɪtnəs fər juz"},
{"id":528,"en":"Conformance to Requirements","say":"Conformance to Requirements","also":[],"gloss":"符合要求","explain":"克劳斯比的说法：质量就是符合事先定下的要求。","band":"治理","ipa":"kənˈfɔrməns tɪ rɪkˈwaɪrmənts"},
{"id":529,"en":"Zero Defects","say":"Zero Defects","also":[],"gloss":"零缺陷","explain":"克劳斯比主张第一次就做对，而不是靠后期挑错。","band":"治理","ipa":"ˈziroʊ ˈdifɛkts"},
{"id":530,"en":"Voice of the Customer (VOC)","say":"Voice of the Customer","also":["voc"],"gloss":"客户之声","explain":"把客户真正的需要说清楚，作为设计和质量的输入。","band":"治理","ipa":"vɔɪs əv ðə ˈkəstəmər"},
{"id":531,"en":"Quality Function Deployment (QFD)","say":"Quality Function Deployment","also":["qfd"],"gloss":"质量功能展开","explain":"把客户需求转化成设计要求的一套方法。","band":"治理","ipa":"kˈwɑləti ˈfəŋkʃən dɪˈplɔɪmənt"},
{"id":532,"en":"House of Quality","say":"House of Quality","also":[],"gloss":"质量屋","explain":"和质量要求、测量或保证有关。记住：质量是符合要求，不是档次高低。","band":"治理","ipa":"haʊs əv kˈwɑləti"},
{"id":533,"en":"Deming","say":"Deming","also":[],"gloss":"戴明","explain":"质量先驱，强调管理层责任、减少变异和 PDCA。","band":"治理","ipa":"ˈdɛmɪŋ"},
{"id":534,"en":"Juran","say":"Juran","also":[],"gloss":"朱兰","explain":"质量先驱，提出适用性，并把质量分成计划、控制和改进。","band":"治理","ipa":"jʊˈrɑn"},
{"id":535,"en":"Crosby","say":"Crosby","also":[],"gloss":"克劳斯比","explain":"质量先驱，主张质量免费、符合要求和零缺陷。","band":"治理","ipa":"ˈkrɔzbi"},
{"id":536,"en":"Ishikawa","say":"Ishikawa","also":[],"gloss":"石川馨","explain":"提出因果图和质量圈，强调一线人员参与改进。","band":"治理","ipa":"ˌɪˌʃiˈkɑˌwɑ"},
{"id":537,"en":"Taguchi","say":"Taguchi","also":[],"gloss":"田口玄一","explain":"用质量损失函数说明：偏离目标值就会造成损失。","band":"治理","ipa":"taguchi"},
{"id":538,"en":"Shewhart","say":"Shewhart","also":[],"gloss":"休哈特","explain":"统计过程控制的奠基人，控制图从他这里来。","band":"治理","ipa":"shewhart"},
{"id":539,"en":"Customer Satisfaction","say":"Customer Satisfaction","also":[],"gloss":"客户满意","explain":"成果在多大程度上满足客户期望，是质量是否成立的外部判断。","band":"治理","ipa":"ˈkəstəmər ˌsætɪsˈfækʃən"},
{"id":540,"en":"Defect","say":"Defect","also":[],"gloss":"缺陷","explain":"不符合要求的地方。发现得越晚，补救通常越贵。","band":"治理","ipa":"ˈdifɛkt"},
{"id":541,"en":"Rework","say":"Rework","also":[],"gloss":"返工","explain":"因为不合格而重新做一遍，既费时间也费钱。","band":"治理","ipa":"riˈwərk"},
{"id":542,"en":"Scrap","say":"Scrap","also":[],"gloss":"报废","explain":"缺陷严重到只能报废，投入收不回来。","band":"治理","ipa":"skræp"},
{"id":964,"en":"Postmortem","say":"Postmortem","also":[],"gloss":"复盘","explain":"大版本或项目结束后回顾哪里偏离了计划。它比一次冲刺回顾看得更长。","band":"治理","ipa":"poʊstˈmɔrtɛm","tag":"游戏"},
{"id":215,"en":"Information Management","say":"Information Management","also":[],"gloss":"信息管理","explain":"把显性知识做成文档、登记册和检索，方便别人找到。","band":"组织","ipa":"ˌɪnˌfɔrˈmeɪʃən ˈmænɪʤmənt"},
{"id":216,"en":"Project Management Office (PMO)","say":"Project Management Office","also":["pmo"],"gloss":"项目管理办公室","explain":"把项目管理标准化，并按类型向项目提供支持、控制或直接管理。","band":"组织","ipa":"ˈprɑʤɛkt ˈmænɪʤmənt ˈɔfəs"},
{"id":217,"en":"Supportive PMO","say":"Supportive PMO","also":[],"gloss":"支持型项目管理办公室","explain":"主要提供模板、培训和咨询，对项目的控制权低。","band":"组织","ipa":"səˈpɔrtɪv pi ɛm oʊ"},
{"id":218,"en":"Controlling PMO","say":"Controlling PMO","also":[],"gloss":"控制型项目管理办公室","explain":"要求项目遵守框架和方法，控制程度中等。","band":"组织","ipa":"kənˈtroʊlɪŋ pi ɛm oʊ"},
{"id":219,"en":"Directive PMO","say":"Directive PMO","also":[],"gloss":"指令型项目管理办公室","explain":"直接管理项目，控制程度最高。","band":"组织","ipa":"dɪˈrɛktɪv pi ɛm oʊ"},
{"id":220,"en":"Portfolio","say":"Portfolio","also":[],"gloss":"项目组合","explain":"为了战略目标放在一起管理的一群项目、项目集和运营工作。","band":"组织","ipa":"pɔrtˈfoʊliˌoʊ"},
{"id":221,"en":"Program","say":"Program","also":[],"gloss":"项目集","explain":"相互关联、必须协调才能拿到单独管理得不到的收益的一组项目。","band":"组织","ipa":"ˈproʊˌgræm"},
{"id":222,"en":"Portfolio Management","say":"Portfolio Management","also":[],"gloss":"项目组合管理","explain":"选择和排定一群项目，使它们符合组织战略。","band":"组织","ipa":"pɔrtˈfoʊliˌoʊ ˈmænɪʤmənt"},
{"id":223,"en":"Program Management","say":"Program Management","also":[],"gloss":"项目集管理","explain":"协调一组相关项目，拿到分开管理拿不到的收益。","band":"组织","ipa":"ˈproʊˌgræm ˈmænɪʤmənt"},
{"id":224,"en":"Operations","say":"Operations","also":[],"gloss":"运营","explain":"持续、重复地生产产品或提供服务，没有项目那样的终点。","band":"组织","ipa":"ˌɑpərˈeɪʃənz"},
{"id":225,"en":"Operations Management","say":"Operations Management","also":[],"gloss":"运营管理","explain":"负责日常运营。项目的成果最终要交到运营里去用。","band":"组织","ipa":"ˌɑpərˈeɪʃənz ˈmænɪʤmənt"},
{"id":226,"en":"Functional Organization","say":"Functional Organization","also":[],"gloss":"职能型组织","explain":"按职能划分部门，项目经理权力很小，资源归职能经理。","band":"组织","ipa":"ˈfəŋkʃənəl ˌɔrgənəˈzeɪʃən"},
{"id":227,"en":"Matrix Organization","say":"Matrix Organization","also":[],"gloss":"矩阵型组织","explain":"组织结构的一种。它决定项目经理能不能直接调用人。","band":"组织","ipa":"ˈmeɪtrɪks ˌɔrgənəˈzeɪʃən"},
{"id":228,"en":"Weak Matrix","say":"Weak Matrix","also":[],"gloss":"弱矩阵","explain":"仍偏职能型，项目经理更像协调员，权力弱。","band":"组织","ipa":"wik ˈmeɪtrɪks"},
{"id":229,"en":"Balanced Matrix","say":"Balanced Matrix","also":[],"gloss":"平衡矩阵","explain":"项目经理和职能经理分享权力。","band":"组织","ipa":"ˈbælənst ˈmeɪtrɪks"},
{"id":230,"en":"Strong Matrix","say":"Strong Matrix","also":[],"gloss":"强矩阵","explain":"项目经理权力大，接近项目型组织。","band":"组织","ipa":"strɔŋ ˈmeɪtrɪks"},
{"id":231,"en":"Projectized Organization","say":"Projectized Organization","also":[],"gloss":"项目型组织","explain":"按项目组建，项目经理权力最大，团队常常全职投入。","band":"组织","ipa":"projectized ˌɔrgənəˈzeɪʃən"},
{"id":232,"en":"Organic Organization","say":"Organic Organization","also":[],"gloss":"有机型组织","explain":"组织结构的一种。它决定项目经理能不能直接调用人。","band":"组织","ipa":"ɔrˈgænɪk ˌɔrgənəˈzeɪʃən"},
{"id":233,"en":"Virtual Organization","say":"Virtual Organization","also":[],"gloss":"虚拟型组织","explain":"组织结构的一种。它决定项目经理能不能直接调用人。","band":"组织","ipa":"ˈvərʧuəl ˌɔrgənəˈzeɪʃən"},
{"id":234,"en":"Hybrid Organization","say":"Hybrid Organization","also":[],"gloss":"混合型组织","explain":"组织结构的一种。它决定项目经理能不能直接调用人。","band":"组织","ipa":"ˈhaɪbrɪd ˌɔrgənəˈzeɪʃən"},
{"id":235,"en":"Functional Manager","say":"Functional Manager","also":[],"gloss":"职能经理","explain":"职能部门的负责人，掌握专业资源和人员考核。","band":"组织","ipa":"ˈfəŋkʃənəl ˈmænɪʤər"},
{"id":236,"en":"Program Manager","say":"Program Manager","also":[],"gloss":"项目集经理","explain":"负责一个项目集，协调其中多个项目的依赖和收益。","band":"组织","ipa":"ˈproʊˌgræm ˈmænɪʤər"},
{"id":237,"en":"Portfolio Manager","say":"Portfolio Manager","also":[],"gloss":"项目组合经理","explain":"负责项目组合，决定哪些项目该做、哪些该停。","band":"组织","ipa":"pɔrtˈfoʊliˌoʊ ˈmænɪʤər"},
{"id":238,"en":"Project Coordinator","say":"Project Coordinator","also":[],"gloss":"项目协调员","explain":"有一定协调权，可以向高层汇报，但权力仍有限。","band":"组织","ipa":"ˈprɑʤɛkt koʊˈɔrdəˌneɪtər"},
{"id":239,"en":"Project Expeditor","say":"Project Expeditor","also":[],"gloss":"项目联络员","explain":"几乎没有决策权，主要是传话和催进度的联络员。","band":"组织","ipa":"ˈprɑʤɛkt expeditor"},
{"id":240,"en":"Performing Organization","say":"Performing Organization","also":[],"gloss":"执行组织","explain":"组织结构的一种。它决定项目经理能不能直接调用人。","band":"组织","ipa":"pərˈfɔrmɪŋ ˌɔrgənəˈzeɪʃən"},
{"id":241,"en":"Phase Gate","say":"Phase Gate","also":[],"gloss":"阶段关口","explain":"阶段结束时的检查点，决定继续、修改还是停止。","band":"组织","ipa":"feɪz geɪt"},
{"id":242,"en":"Kill Point","say":"Kill Point","also":[],"gloss":"终止点","explain":"阶段关口上可以叫停项目的决策点。","band":"组织","ipa":"kɪl pɔɪnt"},
{"id":243,"en":"Go/No-Go Decision","say":"Go/No-Go Decision","also":[],"gloss":"继续或终止决策","explain":"在关口上决定继续前进，还是停止。","band":"组织","ipa":"goʊ ˈnoʊˌgoʊ dɪˈsɪʒən"},
{"id":244,"en":"Feasibility Study","say":"Feasibility Study","also":[],"gloss":"可行性研究","explain":"项目正式大做之前，先看技术、经济和运营上是否可行。","band":"组织","ipa":"ˌfizəˈbɪləti ˈstədi"},
{"id":245,"en":"Tailoring","say":"Tailoring","also":[],"gloss":"裁剪","explain":"按项目的规模、风险和背景，挑选并调整适用的方法，而不是全盘照搬。","band":"组织","ipa":"ˈteɪlərɪŋ"},
{"id":255,"en":"Business Justification Analysis","say":"Business Justification Analysis","also":[],"gloss":"商业合理性分析","explain":"一种分析技术，用来比较方案、追查原因或预测结果。","band":"组织","ipa":"ˈbɪznɪs ˌʤəstəfəˈkeɪʃən æˈnælɪsɪs"},
{"id":256,"en":"Performance Domain","say":"Performance Domain","also":[],"gloss":"绩效域","explain":"第7版的绩效域：一组决定项目能否交付成果的相关活动，不按旧版过程步骤来记。","band":"组织","ipa":"pərˈfɔrməns doʊˈmeɪn"},
{"id":257,"en":"Stakeholder Performance Domain","say":"Stakeholder Performance Domain","also":[],"gloss":"干系人绩效域","explain":"第7版的绩效域：一组决定项目能否交付成果的相关活动，不按旧版过程步骤来记。","band":"组织","ipa":"ˈsteɪˌkhoʊldər pərˈfɔrməns doʊˈmeɪn"},
{"id":258,"en":"Team Performance Domain","say":"Team Performance Domain","also":[],"gloss":"团队绩效域","explain":"第7版的绩效域：一组决定项目能否交付成果的相关活动，不按旧版过程步骤来记。","band":"组织","ipa":"tim pərˈfɔrməns doʊˈmeɪn"},
{"id":259,"en":"Development Approach and Life Cycle Performance Domain","say":"Development Approach and Life Cycle Performance Domain","also":[],"gloss":"开发方法和生命周期绩效域","explain":"第7版的绩效域：一组决定项目能否交付成果的相关活动，不按旧版过程步骤来记。","band":"组织","ipa":"dɪˈvɛləpmənt əˈproʊʧ ənd laɪf ˈsaɪkəl pərˈfɔrməns doʊˈmeɪn"},
{"id":260,"en":"Planning Performance Domain","say":"Planning Performance Domain","also":[],"gloss":"规划绩效域","explain":"第7版的绩效域：一组决定项目能否交付成果的相关活动，不按旧版过程步骤来记。","band":"组织","ipa":"ˈplænɪŋ pərˈfɔrməns doʊˈmeɪn"},
{"id":261,"en":"Project Work Performance Domain","say":"Project Work Performance Domain","also":[],"gloss":"项目工作绩效域","explain":"第7版的绩效域：一组决定项目能否交付成果的相关活动，不按旧版过程步骤来记。","band":"组织","ipa":"ˈprɑʤɛkt wərk pərˈfɔrməns doʊˈmeɪn"},
{"id":262,"en":"Delivery Performance Domain","say":"Delivery Performance Domain","also":[],"gloss":"交付绩效域","explain":"第7版的绩效域：一组决定项目能否交付成果的相关活动，不按旧版过程步骤来记。","band":"组织","ipa":"dɪˈlɪvəri pərˈfɔrməns doʊˈmeɪn"},
{"id":263,"en":"Measurement Performance Domain","say":"Measurement Performance Domain","also":[],"gloss":"测量绩效域","explain":"第7版的绩效域：一组决定项目能否交付成果的相关活动，不按旧版过程步骤来记。","band":"组织","ipa":"ˈmɛʒərmənt pərˈfɔrməns doʊˈmeɪn"},
{"id":264,"en":"Uncertainty Performance Domain","say":"Uncertainty Performance Domain","also":[],"gloss":"不确定性绩效域","explain":"第7版的绩效域：一组决定项目能否交付成果的相关活动，不按旧版过程步骤来记。","band":"组织","ipa":"ənˈsərtənti pərˈfɔrməns doʊˈmeɪn"},
{"id":265,"en":"Project Management Principle","say":"Project Management Principle","also":[],"gloss":"项目管理原则","explain":"第7版的行为指南，不是必须逐步执行的过程。","band":"组织","ipa":"ˈprɑʤɛkt ˈmænɪʤmənt ˈprɪnsəpəl"},
{"id":266,"en":"Stewardship","say":"Stewardship","also":[],"gloss":"管家式管理","explain":"以正直、关心和合规的方式看管项目，对财务、社会和环境影响负责。","band":"组织","ipa":"ˈstuərdˌʃɪp"},
{"id":267,"en":"Collaborative Project Team Environment","say":"Collaborative Project Team Environment","also":[],"gloss":"协作的项目团队环境","explain":"让团队有共同目标、清楚协议和能说话的环境。","band":"组织","ipa":"kəˈlæbərˌeɪtɪv ˈprɑʤɛkt tim ɪnˈvaɪrənmənt"},
{"id":268,"en":"Focus on Value","say":"Focus on Value","also":[],"gloss":"聚焦于价值","explain":"决策始终回到值不值得，而不是只盯着做完任务。","band":"组织","ipa":"ˈfoʊkɪs ɔn ˈvælju"},
{"id":269,"en":"System Interaction","say":"System Interaction","also":[],"gloss":"系统交互","explain":"项目内外各部分会互相影响，改一处要看别处的反应。","band":"组织","ipa":"ˈsɪstəm ˌɪnərˈækʃən"},
{"id":270,"en":"Systems Thinking","say":"Systems Thinking","also":[],"gloss":"系统思考","explain":"把项目看成相互关联的整体，而不是孤立的任务清单。","band":"组织","ipa":"ˈsɪstəmz ˈθɪŋkɪŋ"},
{"id":271,"en":"Leadership Behavior","say":"Leadership Behavior","also":[],"gloss":"领导力行为","explain":"在项目里展现的带领方式，可以随情境变化。","band":"组织","ipa":"ˈlidərˌʃɪp bɪˈheɪvjər"},
{"id":272,"en":"Built-in Quality","say":"Built-in Quality","also":[],"gloss":"将质量融入过程和可交付物","explain":"和质量要求、测量或保证有关。记住：质量是符合要求，不是档次高低。","band":"组织","ipa":"ˈbɪlˌtɪn kˈwɑləti"},
{"id":273,"en":"Complexity","say":"Complexity","also":[],"gloss":"复杂性","explain":"因人的行为、系统交互或不确定性而难以简单预测的程度。","band":"组织","ipa":"kəmˈplɛksɪti"},
{"id":274,"en":"Adaptability","say":"Adaptability","also":[],"gloss":"适应性","explain":"根据新信息调整计划和做法的能力。","band":"组织","ipa":"əˌdæptəˈbɪləti"},
{"id":275,"en":"Resiliency","say":"Resiliency","also":[],"gloss":"韧性","explain":"受到冲击后还能恢复并继续交付的能力。","band":"组织","ipa":"rɪˈzɪljənsi"},
{"id":276,"en":"Enable Change","say":"Enable Change","also":[],"gloss":"驱动变革","explain":"和修改已批准的计划或成果有关，通常要留下请求和批准记录。","band":"组织","ipa":"ɪˈneɪbəl ʧeɪnʤ"},
{"id":277,"en":"Artifact","say":"Artifact","also":[],"gloss":"工件","explain":"项目里产生的文件、图或模板，比如章程、登记册和燃尽图。","band":"组织","ipa":"ˈɑrtəˌfækt"},
{"id":278,"en":"Model","say":"Model","also":[],"gloss":"模型","explain":"解释某种现象的思考框架，比如塔克曼阶段或冲突模型。","band":"组织","ipa":"ˈmɑdəl"},
{"id":279,"en":"Method","say":"Method","also":[],"gloss":"方法","explain":"完成某类工作的手段，比如估算方法或开回顾会。","band":"组织","ipa":"ˈmɛθəd"},
{"id":543,"en":"Responsibility Assignment Matrix (RAM)","say":"Responsibility Assignment Matrix","also":["ram"],"gloss":"责任分配矩阵","explain":"把工作包和人对应起来，显示谁执行、谁问责。","band":"协作","ipa":"riˌspɑnsəˈbɪləti əˈsaɪnmənt ˈmeɪtrɪks"},
{"id":544,"en":"RACI Matrix","say":"RACI Matrix","also":[],"gloss":"RACI 矩阵：执行、负责、咨询、知情","explain":"责任分配矩阵。R 是动手做的人，A 是唯一被问责的人，C 是被咨询的人，I 是被通知的人。","band":"协作","ipa":"ɑr eɪ si aɪ ˈmeɪtrɪks"},
{"id":545,"en":"Responsible","say":"Responsible","also":[],"gloss":"执行","explain":"RACI 中的 R。","band":"协作","ipa":"riˈspɑnsəbəl"},
{"id":546,"en":"Accountable","say":"Accountable","also":[],"gloss":"负责","explain":"RACI 中的 A，唯一问责人。","band":"协作","ipa":"əˈkaʊntəbəl"},
{"id":547,"en":"Consulted","say":"Consulted","also":[],"gloss":"咨询","explain":"RACI 中的 C。","band":"协作","ipa":"kənˈsəltɪd"},
{"id":548,"en":"Informed","say":"Informed","also":[],"gloss":"知情","explain":"RACI 中的 I。","band":"协作","ipa":"ˌɪnˈfɔrmd"},
{"id":549,"en":"Organizational Breakdown Structure (OBS)","say":"Organizational Breakdown Structure","also":["obs"],"gloss":"组织分解结构","explain":"按组织部门把工作责任分解开，常和 WBS 交叉。","band":"协作","ipa":"ˌɔrgənəˈzeɪʃənəl ˈbreɪkˌdaʊn ˈstrəkʧər"},
{"id":550,"en":"Resource Breakdown Structure","say":"Resource Breakdown Structure","also":[],"gloss":"资源分解结构","explain":"按类别列出项目需要的资源，便于估算和获取。","band":"协作","ipa":"ˈrisɔrs ˈbreɪkˌdaʊn ˈstrəkʧər"},
{"id":551,"en":"Team Charter","say":"Team Charter","also":[],"gloss":"团队章程","explain":"团队自己约定的价值观、工作协议和行为规则。","band":"协作","ipa":"tim ˈʧɑrtər"},
{"id":552,"en":"Ground Rules","say":"Ground Rules","also":[],"gloss":"基本规则","explain":"团队同意遵守的基本行为约定，减少以后的摩擦。","band":"协作","ipa":"graʊnd rulz"},
{"id":553,"en":"Colocation","say":"Colocation","also":[],"gloss":"集中办公","explain":"把团队放在同一地点办公，方便沟通。虚拟团队则相反。","band":"协作","ipa":"colocation"},
{"id":554,"en":"Virtual Team","say":"Virtual Team","also":[],"gloss":"虚拟团队","explain":"和项目团队的建设、管理或工作方式有关。","band":"协作","ipa":"ˈvərʧuəl tim"},
{"id":555,"en":"Resource Requirement","say":"Resource Requirement","also":[],"gloss":"资源需求","explain":"每项活动需要什么资源、需要多少。","band":"协作","ipa":"ˈrisɔrs rɪkˈwaɪrmənt"},
{"id":556,"en":"Recognition and Rewards","say":"Recognition and Rewards","also":[],"gloss":"认可与奖励","explain":"对良好行为给予承认和奖励，用来强化团队想要的做法。","band":"协作","ipa":"ˌrɛkɪgˈnɪʃən ənd rɪˈwɔrdz"},
{"id":557,"en":"Training","say":"Training","also":[],"gloss":"培训","explain":"补足完成项目所缺的技能。它服务于工作，不只是福利。","band":"协作","ipa":"ˈtreɪnɪŋ"},
{"id":558,"en":"Team Building","say":"Team Building","also":[],"gloss":"团队建设","explain":"增强协作和信任的活动，从开工到解散都可以做。","band":"协作","ipa":"tim ˈbɪldɪŋ"},
{"id":559,"en":"Tuckman Ladder","say":"Tuckman Ladder","also":[],"gloss":"塔克曼阶梯","explain":"团队发展常经历形成、震荡、规范、成熟，最后解散。","band":"协作","ipa":"ˈtəkmən ˈlædər"},
{"id":560,"en":"Forming","say":"Forming","also":[],"gloss":"形成","explain":"团队刚组成，成员客气、角色还不清楚。","band":"协作","ipa":"ˈfɔrmɪŋ"},
{"id":561,"en":"Storming","say":"Storming","also":[],"gloss":"震荡","explain":"意见冲突变多，这是建立信任前的常见阶段。","band":"协作","ipa":"ˈstɔrmɪŋ"},
{"id":562,"en":"Norming","say":"Norming","also":[],"gloss":"规范","explain":"团队开始形成默契和共同规则。","band":"协作","ipa":"ˈnɔrmɪŋ"},
{"id":563,"en":"Performing","say":"Performing","also":[],"gloss":"成熟","explain":"团队能高效协作，精力主要放在交付上。","band":"协作","ipa":"pərˈfɔrmɪŋ"},
{"id":564,"en":"Adjourning","say":"Adjourning","also":[],"gloss":"解散","explain":"工作结束，团队解散，需要处理好移交和情绪。","band":"协作","ipa":"əˈʤərnɪŋ"},
{"id":565,"en":"Conflict Management","say":"Conflict Management","also":[],"gloss":"冲突管理","explain":"把分歧处理成能继续共事的结果。面对问题通常优于回避。","band":"协作","ipa":"ˈkɑnflɪkt ˈmænɪʤmənt"},
{"id":566,"en":"Collaborate / Problem Solve","say":"Collaborate, Problem Solve","also":[],"gloss":"合作 / 解决问题","explain":"冲突处理里最彻底的一种：把问题摊开，找到双方都认可的办法。","band":"协作","ipa":"kəˈlæbərˌeɪt, ˈprɑbləm sɑlv"},
{"id":567,"en":"Compromise / Reconcile","say":"Compromise, Reconcile","also":[],"gloss":"妥协 / 调解","explain":"双方各让一步，得到暂时能接受、但未必最优的方案。","band":"协作","ipa":"ˈkɑmprəˌmaɪz, ˈrɛkənˌsaɪl"},
{"id":568,"en":"Smooth / Accommodate","say":"Smooth, Accommodate","also":[],"gloss":"缓和 / 包容","explain":"强调一致、淡化差异，适合维持关系，但问题可能还在。","band":"协作","ipa":"smuð, əˈkɑməˌdeɪt"},
{"id":569,"en":"Force / Direct","say":"Force, Direct","also":[],"gloss":"强迫 / 命令","explain":"靠权力推行一方的决定。紧急时有用，容易伤关系。","band":"协作","ipa":"fɔrs, dɪˈrɛkt"},
{"id":570,"en":"Withdraw / Avoid","say":"Withdraw, Avoid","also":[],"gloss":"撤退 / 回避","explain":"先退出冲突。适合问题很小，或需要冷静的时候。","band":"协作","ipa":"wɪθˈdrɔ, əˈvɔɪd"},
{"id":965,"en":"Associate Producer","say":"Associate Producer","also":[],"gloss":"助理制作人","explain":"在制作人下面盯一条线的进度、会议和跨组依赖的人。","band":"协作","ipa":"əˈsoʊʃiˌeɪt prəˈdusər","tag":"游戏"},
{"id":571,"en":"Competing","say":"Competing","also":[],"gloss":"竞争","explain":"坚持自己的立场、压过对方，和强迫接近。","band":"协作","ipa":"kəmˈpitɪŋ"},
{"id":572,"en":"Accommodating","say":"Accommodating","also":[],"gloss":"迁就","explain":"放弃自己的需要去满足对方。","band":"协作","ipa":"əˈkɑməˌdeɪtɪŋ"},
{"id":573,"en":"Emotional Intelligence","say":"Emotional Intelligence","also":[],"gloss":"情商","explain":"觉察自己和他人的情绪，并据此调整行为的能力。","band":"协作","ipa":"ˈiˌmoʊʃənəl ˌɪnˈtɛləʤəns"},
{"id":574,"en":"Self-awareness","say":"Self-awareness","also":[],"gloss":"自我意识","explain":"知道自己当下的情绪和它会如何影响判断。","band":"协作","ipa":"sɛlf əˈwɛrnəs"},
{"id":575,"en":"Self-management","say":"Self-management","also":[],"gloss":"自我管理","explain":"能管住自己的反应，在压力下仍然把事做完。","band":"协作","ipa":"sɛlf ˈmænɪʤmənt"},
{"id":576,"en":"Social Awareness","say":"Social Awareness","also":[],"gloss":"社交意识","explain":"读得懂别人的情绪和团队气氛。","band":"协作","ipa":"ˈsoʊʃəl əˈwɛrnəs"},
{"id":577,"en":"Social Skill","say":"Social Skill","also":[],"gloss":"社交技能","explain":"能建立关系、影响他人并推动一群人一起工作。","band":"协作","ipa":"ˈsoʊʃəl skɪl"},
{"id":578,"en":"Motivation","say":"Motivation","also":[],"gloss":"激励","explain":"促使人愿意投入的力量。项目经理要知道成员被什么驱动。","band":"协作","ipa":"ˌmoʊtəˈveɪʃən"},
{"id":579,"en":"Coaching","say":"Coaching","also":[],"gloss":"教练","explain":"通过提问和反馈，帮助对方自己找到做法并成长。","band":"协作","ipa":"ˈkoʊʧɪŋ"},
{"id":580,"en":"Mentoring","say":"Mentoring","also":[],"gloss":"辅导","explain":"有经验的人给方向和职业上的指导，时间通常更长。","band":"协作","ipa":"ˈmɛntərɪŋ"},
{"id":581,"en":"Delegation","say":"Delegation","also":[],"gloss":"授权","explain":"把职权和任务交给合适的人，同时保留问责的清晰边界。","band":"协作","ipa":"ˌdɛləˈgeɪʃən"},
{"id":582,"en":"Empowerment","say":"Empowerment","also":[],"gloss":"赋能","explain":"让团队有信息、有权限在现场做决定。","band":"协作","ipa":"ɪmˈpaʊərmənt"},
{"id":583,"en":"Trust","say":"Trust","also":[],"gloss":"信任","explain":"成员相信彼此会说到做到。没有信任，协作会变得很贵。","band":"协作","ipa":"trəst"},
{"id":584,"en":"Psychological Safety","say":"Psychological Safety","also":[],"gloss":"心理安全","explain":"人觉得说出坏消息或不同意见也不会被惩罚。","band":"协作","ipa":"ˌsaɪkəˈlɑʤɪkəl ˈseɪfti"},
{"id":585,"en":"Diversity","say":"Diversity","also":[],"gloss":"多样性","explain":"团队在背景、经验和思维方式上的差异，有助于看全问题。","band":"协作","ipa":"dɪˈvərsɪti"},
{"id":586,"en":"Negotiation","say":"Negotiation","also":[],"gloss":"谈判","explain":"通过商量达成双方都能接受的协议。","band":"协作","ipa":"nɪˌgoʊʃiˈeɪʃən"},
{"id":587,"en":"Influencing","say":"Influencing","also":[],"gloss":"影响","explain":"不靠正式职权，让别人愿意支持你的做法。","band":"协作","ipa":"ˈɪnˌfluənsɪŋ"},
{"id":588,"en":"Active Listening","say":"Active Listening","also":[],"gloss":"积极倾听","explain":"听完、确认自己理解了，再回应，而不是急着反驳。","band":"协作","ipa":"ˈæktɪv ˈlɪsənɪŋ"},
{"id":589,"en":"Facilitation","say":"Facilitation","also":[],"gloss":"引导","explain":"引导一群人把问题讨论清楚并做出决定，主持人不代替他们决定。","band":"协作","ipa":"fəˌsɪləˈteɪʃən"},
{"id":590,"en":"Networking","say":"Networking","also":[],"gloss":"人脉经营","explain":"建立和维护能交换信息、获得支持的人际关系。","band":"协作","ipa":"ˈnɛtˌwərkɪŋ"},
{"id":591,"en":"Political Awareness","say":"Political Awareness","also":[],"gloss":"政治意识","explain":"看懂组织里谁影响谁，避免在不知情下踩到决策结构。","band":"协作","ipa":"pəˈlɪtɪkəl əˈwɛrnəs"},
{"id":592,"en":"Cultural Awareness","say":"Cultural Awareness","also":[],"gloss":"文化意识","explain":"理解不同文化在沟通、时间和权威上的差别。","band":"协作","ipa":"ˈkəlʧərəl əˈwɛrnəs"},
{"id":593,"en":"Meeting Management","say":"Meeting Management","also":[],"gloss":"会议管理","explain":"让会议有目的、有议程、有结论，不把时间耗在漫谈上。","band":"协作","ipa":"ˈmitɪŋ ˈmænɪʤmənt"},
{"id":594,"en":"Expert Judgment","say":"Expert Judgment","also":[],"gloss":"专家判断","explain":"请来有相关经验的人提供判断，几乎每个过程都会用到。","band":"协作","ipa":"ˈɛkspərt ˈʤəʤmənt"},
{"id":595,"en":"Brainstorming","say":"Brainstorming","also":[],"gloss":"头脑风暴","explain":"先尽量多地产生想法，暂不批评，然后再筛选。","band":"协作","ipa":"ˈbreɪnˌstɔrmɪŋ"},
{"id":596,"en":"Interview","say":"Interview","also":[],"gloss":"访谈","explain":"一对一或小组提问，用来收集需求、风险或干系人信息。","band":"协作","ipa":"ˈɪntərvˌju"},
{"id":597,"en":"Focus Group","say":"Focus Group","also":[],"gloss":"焦点小组","explain":"把一组干系人聚在一起，由引导者讨论某个主题。","band":"协作","ipa":"ˈfoʊkɪs grup"},
{"id":598,"en":"Questionnaire and Survey","say":"Questionnaire and Survey","also":[],"gloss":"问卷调查","explain":"用问卷向很多人快速收集比较一致的信息。","band":"协作","ipa":"kˌwɛsʧəˈnɛr ənd ˈsərˌveɪ"},
{"id":966,"en":"QA Lead","say":"Q A Lead","also":[],"gloss":"测试负责人","explain":"组织测试计划、缺陷分诊，并和制作一起确认能不能出货的人。","band":"协作","ipa":"kju ə lɛd","tag":"游戏"},
{"id":599,"en":"Observation","say":"Observation","also":[],"gloss":"观察","explain":"看人实际怎么工作，发现他们说不出来的需求。","band":"协作","ipa":"ˌɑbzərˈveɪʃən"},
{"id":600,"en":"Job Shadowing","say":"Job Shadowing","also":[],"gloss":"工作跟随","explain":"跟着工作者看一整段工作，是观察的一种。","band":"协作","ipa":"ʤɑb ˈʃædoʊɪŋ"},
{"id":601,"en":"Facilitated Workshop","say":"Facilitated Workshop","also":[],"gloss":"引导式研讨会","explain":"把关键干系人集中起来，当场把需求或差异谈拢。","band":"协作","ipa":"fəˈsɪləˌteɪtɪd ˈwərkˌʃɑp"},
{"id":602,"en":"Prototyping","say":"Prototyping","also":[],"gloss":"原型法","explain":"先做样品给干系人试用，再用反馈修正需求。","band":"协作","ipa":"ˈproʊtoʊˌtaɪpɪŋ"},
{"id":603,"en":"Context Diagram","say":"Context Diagram","also":[],"gloss":"系统交互图","explain":"用图把关系、流程或原因摊开，方便团队一起看。","band":"协作","ipa":"ˈkɑntɛkst ˈdaɪəˌgræm"},
{"id":604,"en":"Joint Application Design (JAD)","say":"Joint Application Design","also":["jad"],"gloss":"联合应用设计","explain":"业务和开发一起开的需求研讨会，争取当场定下来。","band":"协作","ipa":"ʤɔɪnt ˌæpləˈkeɪʃən dɪˈzaɪn"},
{"id":605,"en":"Mind Mapping","say":"Mind Mapping","also":[],"gloss":"思维导图","explain":"从中心主题向外画分支，用来整理想法和需求。","band":"协作","ipa":"maɪnd ˈmæpɪŋ"},
{"id":606,"en":"Delphi Technique","say":"Delphi Technique","also":[],"gloss":"德尔菲技术","explain":"专家匿名作答、多轮反馈，减少面对面带来的从众。","band":"协作","ipa":"ˈdɛlfaɪ tɛkˈnik"},
{"id":607,"en":"Wideband Delphi","say":"Wideband Delphi","also":[],"gloss":"宽带德尔菲","explain":"德尔菲的变体：极端估算的人要解释理由，然后大家再估一轮。","band":"协作","ipa":"wideband ˈdɛlfaɪ"},
{"id":608,"en":"Nominal Group Technique","say":"Nominal Group Technique","also":[],"gloss":"名义小组技术","explain":"先独立写下想法，再集体讨论和投票排序。","band":"协作","ipa":"ˈnɑmənəl grup tɛkˈnik"},
{"id":609,"en":"Multicriteria Decision Analysis","say":"Multicriteria Decision Analysis","also":[],"gloss":"多标准决策分析","explain":"一种分析技术，用来比较方案、追查原因或预测结果。","band":"协作","ipa":"multicriteria dɪˈsɪʒən æˈnælɪsɪs"},
{"id":610,"en":"Voting","say":"Voting","also":[],"gloss":"投票","explain":"用集体表决做决定。要听清是一致通过、过半，还是相对多数。","band":"协作","ipa":"ˈvoʊtɪŋ"},
{"id":611,"en":"Unanimity","say":"Unanimity","also":[],"gloss":"一致同意","explain":"所有人都同意才算通过。","band":"协作","ipa":"ˌjunəˈnɪmɪti"},
{"id":612,"en":"Majority","say":"Majority","also":[],"gloss":"大多数原则","explain":"超过一半的人同意即可。","band":"协作","ipa":"məˈʤɔrəti"},
{"id":613,"en":"Plurality","say":"Plurality","also":[],"gloss":"相对多数原则","explain":"得票最多的选项胜出，即使没有过半。","band":"协作","ipa":"plərˈælɪti"},
{"id":614,"en":"Autocratic Decision Making","say":"Autocratic Decision Making","also":[],"gloss":"独裁型决策","explain":"由一个人做决定，适合时间极紧或他是明确的专家。","band":"协作","ipa":"ˌɔtəˈkrætɪk dɪˈsɪʒən ˈmeɪkɪŋ"},
{"id":615,"en":"Alternatives Analysis","say":"Alternatives Analysis","also":[],"gloss":"备选方案分析","explain":"一种分析技术，用来比较方案、追查原因或预测结果。","band":"协作","ipa":"ɔlˈtərnətɪvz æˈnælɪsɪs"},
{"id":616,"en":"Document Analysis","say":"Document Analysis","also":[],"gloss":"文件分析","explain":"一种分析技术，用来比较方案、追查原因或预测结果。","band":"协作","ipa":"ˈdɑkjəmɛnt æˈnælɪsɪs"},
{"id":617,"en":"Data Gathering","say":"Data Gathering","also":[],"gloss":"数据收集","explain":"用头脑风暴、访谈、问卷等方式把信息收集上来。","band":"协作","ipa":"ˈdætə ˈgæðərɪŋ"},
{"id":618,"en":"Data Analysis","say":"Data Analysis","also":[],"gloss":"数据分析","explain":"一种分析技术，用来比较方案、追查原因或预测结果。","band":"协作","ipa":"ˈdætə æˈnælɪsɪs"},
{"id":619,"en":"Interpersonal and Team Skills","say":"Interpersonal and Team Skills","also":[],"gloss":"人际关系与团队技能","explain":"对人的技能，比如引导、谈判、冲突管理和积极倾听。","band":"协作","ipa":"ˌɪntərˈpərsənəl ənd tim skɪlz"},
{"id":620,"en":"Communication Model","say":"Communication Model","also":[],"gloss":"沟通模型","explain":"信息从发送方编码，经媒介到接收方解码，中间还有噪声和反馈。","band":"协作","ipa":"kəmˌjunəˈkeɪʃən ˈmɑdəl"},
{"id":621,"en":"Sender","say":"Sender","also":[],"gloss":"发送方","explain":"把想法变成信息发出去的人。","band":"协作","ipa":"ˈsɛndər"},
{"id":622,"en":"Receiver","say":"Receiver","also":[],"gloss":"接收方","explain":"收到信息并试图理解的人。","band":"协作","ipa":"rɪˈsivər"},
{"id":623,"en":"Encode","say":"Encode","also":[],"gloss":"编码","explain":"发送方把想法变成语言、文字或图表。","band":"协作","ipa":"ɛnˈkoʊd"},
{"id":624,"en":"Decode","say":"Decode","also":[],"gloss":"解码","explain":"接收方把收到的信号理解成意思。","band":"协作","ipa":"dɪˈkoʊd"},
{"id":625,"en":"Medium","say":"Medium","also":[],"gloss":"媒介","explain":"信息走的通道，比如邮件、会议或即时消息。","band":"协作","ipa":"ˈmidiəm"},
{"id":626,"en":"Noise","say":"Noise","also":[],"gloss":"噪声","explain":"干扰理解的因素，包括偏见、距离和术语不通。","band":"协作","ipa":"nɔɪz"},
{"id":967,"en":"Publisher Producer","say":"Publisher Producer","also":[],"gloss":"发行制作人","explain":"发行方负责对接里程碑、验收和对外节点的人。","band":"协作","ipa":"ˈpəblɪʃər prəˈdusər","tag":"游戏"},
{"id":627,"en":"Feedback","say":"Feedback","also":[],"gloss":"反馈","explain":"接收方回应，用来确认信息有没有被正确理解。","band":"协作","ipa":"ˈfidˌbæk"},
{"id":628,"en":"Message","say":"Message","also":[],"gloss":"信息","explain":"被传递的内容本身。","band":"协作","ipa":"ˈmɛsɪʤ"},
{"id":629,"en":"Interactive Communication","say":"Interactive Communication","also":[],"gloss":"互动沟通","explain":"和信息如何产生、发送、接收有关。","band":"协作","ipa":"ˌɪnərˈæktɪv kəmˌjunəˈkeɪʃən"},
{"id":630,"en":"Push Communication","say":"Push Communication","also":[],"gloss":"推式沟通","explain":"和信息如何产生、发送、接收有关。","band":"协作","ipa":"pʊʃ kəmˌjunəˈkeɪʃən"},
{"id":631,"en":"Pull Communication","say":"Pull Communication","also":[],"gloss":"拉式沟通","explain":"和信息如何产生、发送、接收有关。","band":"协作","ipa":"pʊl kəmˌjunəˈkeɪʃən"},
{"id":632,"en":"Communication Channel","say":"Communication Channel","also":[],"gloss":"沟通渠道","explain":"人与人之间的沟通路径。人数一多，路径数量会急剧增加。","band":"协作","ipa":"kəmˌjunəˈkeɪʃən ˈʧænəl"},
{"id":633,"en":"Formal Communication","say":"Formal Communication","also":[],"gloss":"正式沟通","explain":"和信息如何产生、发送、接收有关。","band":"协作","ipa":"ˈfɔrməl kəmˌjunəˈkeɪʃən"},
{"id":634,"en":"Informal Communication","say":"Informal Communication","also":[],"gloss":"非正式沟通","explain":"和信息如何产生、发送、接收有关。","band":"协作","ipa":"ˌɪnˈfɔrməl kəmˌjunəˈkeɪʃən"},
{"id":635,"en":"Communication Styles Assessment","say":"Communication Styles Assessment","also":[],"gloss":"沟通风格评估","explain":"识别干系人偏好的沟通方式，再调整怎么跟他们说。","band":"协作","ipa":"kəmˌjunəˈkeɪʃən staɪlz əˈsɛsmənt"},
{"id":636,"en":"Stakeholder Analysis","say":"Stakeholder Analysis","also":[],"gloss":"干系人分析","explain":"一种分析技术，用来比较方案、追查原因或预测结果。","band":"协作","ipa":"ˈsteɪˌkhoʊldər æˈnælɪsɪs"},
{"id":637,"en":"Stakeholder Engagement","say":"Stakeholder Engagement","also":[],"gloss":"干系人参与","explain":"让干系人按项目需要的程度参与进来，而不是只被通知一声。","band":"协作","ipa":"ˈsteɪˌkhoʊldər ɛnˈgeɪʤmənt"},
{"id":638,"en":"Stakeholder Engagement Assessment Matrix","say":"Stakeholder Engagement Assessment Matrix","also":[],"gloss":"干系人参与度评估矩阵","explain":"一种组织或分析表。若是组织结构，核心是项目经理和职能经理如何分权。","band":"协作","ipa":"ˈsteɪˌkhoʊldər ɛnˈgeɪʤmənt əˈsɛsmənt ˈmeɪtrɪks"},
{"id":639,"en":"Unaware","say":"Unaware","also":[],"gloss":"不知晓","explain":"参与度的最低一档：还不知道项目的存在。","band":"协作","ipa":"ˌənəˈwɛr"},
{"id":640,"en":"Resistant","say":"Resistant","also":[],"gloss":"抵制","explain":"知道项目，但反对或不愿配合。","band":"协作","ipa":"rɪˈzɪstənt"},
{"id":641,"en":"Neutral","say":"Neutral","also":[],"gloss":"中立","explain":"知道项目，既不支持也不反对。","band":"协作","ipa":"ˈnutrəl"},
{"id":642,"en":"Supportive","say":"Supportive","also":[],"gloss":"支持","explain":"了解项目并愿意支持。","band":"协作","ipa":"səˈpɔrtɪv"},
{"id":643,"en":"Leading","say":"Leading","also":[],"gloss":"领导","explain":"不仅支持，还会主动带动别人参与。","band":"协作","ipa":"ˈlidɪŋ"},
{"id":644,"en":"Power/Interest Grid","say":"Power/Interest Grid","also":[],"gloss":"权力 / 利益方格","explain":"按权力和利益高低给干系人分类，决定重点管理谁。","band":"协作","ipa":"paʊər ˈɪntəˌrɛst grɪd"},
{"id":645,"en":"Power/Influence Grid","say":"Power/Influence Grid","also":[],"gloss":"权力 / 影响方格","explain":"按权力和影响给干系人分类。","band":"协作","ipa":"paʊər ˈɪnfluəns grɪd"},
{"id":646,"en":"Impact/Influence Grid","say":"Impact/Influence Grid","also":[],"gloss":"作用 / 影响方格","explain":"按对项目的作用和影响力给干系人分类。","band":"协作","ipa":"ˌɪmˈpækt ˈɪnfluəns grɪd"},
{"id":647,"en":"Salience Model","say":"Salience Model","also":[],"gloss":"显著性模型","explain":"用权力、紧迫性和合法性三个维度描述干系人。","band":"协作","ipa":"salience ˈmɑdəl"},
{"id":648,"en":"Legitimacy","say":"Legitimacy","also":[],"gloss":"合法性","explain":"这个人参与项目在多大程度上是名正言顺的。","band":"协作","ipa":"lɪˈʤɪtəməsi"},
{"id":649,"en":"Urgency","say":"Urgency","also":[],"gloss":"紧迫性","explain":"这个人的诉求需要多快得到回应。","band":"协作","ipa":"ˈərʤənsi"},
{"id":650,"en":"Power","say":"Power","also":[],"gloss":"权力","explain":"影响别人的一种力量来源，可能来自职位、专业、奖惩或人格。","band":"协作","ipa":"paʊər"},
{"id":651,"en":"Direction of Influence","say":"Direction of Influence","also":[],"gloss":"影响方向","explain":"干系人相对项目是向上、向下、向外还是横向施加影响。","band":"协作","ipa":"dɪˈrɛkʃɪn əv ˈɪnfluəns"},
{"id":652,"en":"Upward Influence","say":"Upward Influence","also":[],"gloss":"向上影响","explain":"影响对象是发起人、高管等上面的人。","band":"协作","ipa":"ˈəpwərd ˈɪnfluəns"},
{"id":653,"en":"Downward Influence","say":"Downward Influence","also":[],"gloss":"向下影响","explain":"影响对象是团队或下属。","band":"协作","ipa":"ˈdaʊnwərd ˈɪnfluəns"},
{"id":654,"en":"Outward Influence","say":"Outward Influence","also":[],"gloss":"向外影响","explain":"影响对象是供应商、客户、监管方等外部的人。","band":"协作","ipa":"ˈaʊtwərd ˈɪnfluəns"},
{"id":968,"en":"Localization Producer","say":"Localization Producer","also":[],"gloss":"本地化制作人","explain":"专门排翻译、录音和本地化测试，让各语言版本赶上发布的人。","band":"协作","ipa":"ˌloʊkələˈzeɪʃən prəˈdusər","tag":"游戏"},
{"id":655,"en":"Sideward Influence","say":"Sideward Influence","also":[],"gloss":"横向影响","explain":"影响对象是同级的其他项目经理或部门。","band":"协作","ipa":"sideward ˈɪnfluəns"},
{"id":909,"en":"Product Manager","say":"Product Manager","also":[],"gloss":"产品经理","explain":"对产品的市场、方向和商业结果负责，和产品负责人的侧重点可能不同。","band":"协作","ipa":"ˈprɑdəkt ˈmænɪʤər"},
{"id":365,"en":"Process Group","say":"Process Group","also":[],"gloss":"过程组","explain":"按项目时间逻辑归类的一组过程：启动、规划、执行、监控、收尾。","band":"过程","ipa":"ˈprɔˌsɛs grup"},
{"id":366,"en":"Initiating Process Group","say":"Initiating Process Group","also":[],"gloss":"启动过程组","explain":"正式授权项目或阶段开始，产出章程并识别干系人。","band":"过程","ipa":"ˌɪˈnɪʃiˌeɪtɪŋ ˈprɔˌsɛs grup"}
]);
